def go_json_error(source, error):
    """Translate frequent encoding/json diagnostics to its user-facing wording."""
    pos=error.pos
    line=error.lineno
    source_column=pos-(source.rfind('\n',0,pos)+1)+2
    # Go reports columns one based, while its parser's offending-byte offsets
    # differ from Python by one in the common object-key/value cases.
    col=error.colno
    msg=error.msg
    if msg.startswith('Expecting property name enclosed in double quotes'):
        while pos<len(source) and source[pos].isspace(): pos+=1
        if pos>=len(source): return f'line {line}, column {col}: unexpected end of JSON input'
        ch=source[pos]
        return f"line {line}, column {source_column}: invalid character {ch!r} looking for beginning of object key string"
    if msg=='Expecting value':
        while pos<len(source) and source[pos].isspace(): pos+=1
        if pos>=len(source): return f'line {line}, column {col}: unexpected end of JSON input'
        ch=source[pos]
        return f"line {line}, column {source_column}: invalid character {ch!r} looking for beginning of value"
    if msg.startswith('Unterminated string') or msg=='Expecting value' and pos>=len(source):
        return f'line {line}, column {col}: unexpected end of JSON input'
    return str(error)

def strip_jsonc_comments(source):
    """Remove JSONC comments while preserving comment-like text in strings."""
