                    elif ch=='\\': escaped=True
                    elif ch==quote: quote=None
                elif ch in ('"',"'"): quote=ch
                elif ch in '[{': brackets.append(ch)
                elif ch in ']}':
                    if not brackets or (ch==']' and brackets[-1]!='[') or (ch=='}' and brackets[-1]!='{'):
                        raise ValueError(f'line {n}: mismatched flow collection delimiter')
                    brackets.pop()
            if brackets: raise ValueError(f'line {n}: unexpected end of flow collection')

