    root={}
    stack=[(-1,root)]
    for indent,t in lines:
        while len(stack)>1 and indent<=stack[-1][0]: stack.pop()
        parent=stack[-1][1]
        if t.startswith('- '):
            if not isinstance(parent,list): continue
            parent.append(scalar(t[2:].strip()))
        elif ':' in t:
            key,raw=t.split(':',1); key=key.strip().strip('"\''); raw=raw.strip()
